<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {request} from '../api'
import {newId} from '../ids'
import {confirmAction} from '../ui/confirm'
import ArticleBody from '../reading/ArticleBody.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
import {preferenceFlags} from './preferences'
import type {AICapture,AIApply} from './selection'
const props=defineProps<{creation?:boolean;typeSlug:string;templateSlug?:string;title:string;displayDate:string;disabled?:boolean;capture:()=>AICapture|null;apply:(id:string,text:string,mode:AIApply)=>boolean}>()
const emit=defineEmits<{(e:'preview',jobId:string):void;(e:'pending',value:boolean):void;(e:'dirty',value:boolean):void}>()
const router=useRouter(),config=ref<any>(null),provider=ref(''),action=ref('generate'),materials=ref(''),scope=ref<'none'|'selection'|'body'>(props.creation?'none':'selection'),consent=ref(false)
const media=ref<any[]>([]),mediaQuery=ref(''),mediaBusy=ref(false),selectedIds=ref<string[]>([]),sendPixels=ref(false),temporary=ref<Record<string,boolean|string>>({})
const visionModel=computed(()=>!!config.value?.providers.find((p:any)=>p.id===provider.value)?.vision)
const capture=ref<AICapture|null>(null),result=ref<any>(null),pending=ref(false),error=ref(''),notice=ref(''),callId=ref(''),requestKey=ref('')
let lastFingerprint=''
let alive=true,timer:ReturnType<typeof setTimeout>|undefined
const actions=[['generate','完整文章生成'],['polish','选区润色'],['expand','扩写'],['continue','续写'],['title','标题建议'],['summary','摘要生成'],['tags','标签建议'],['fields','动态字段建议'],['trip','旅行行程建议'],['review','美食点评']]
const candidate=computed(()=>result.value?.preview?.input?.records?.[0])
const plainBody=computed(()=>{const p=result.value?.preview,r=candidate.value;return !!r&&!!r.body.trim()&&['generate','polish','expand','continue','review'].includes(action.value)&&p.valid&&!p.stale_context&&p.input.media.every((m:any)=>m.existing_id&&selectedText.value.includes(m.existing_id))&&p.input.places.every((place:any)=>place.existing_id&&selectedText.value.includes(place.existing_id))&&!/\{\{(?:media|place):/.test(r.body)&&!r.foods.length&&!r.links.length&&!r.travel?.activities.length})
const selectedText=computed(()=>capture.value?(scope.value==='body'?capture.value.body:scope.value==='selection'?capture.value.selection:''):'')
function prepareRange(){capture.value=props.capture();consent.value=false;result.value=null;notice.value=capture.value?'已固定发送范围，请检查下面的文字并明确确认。':'请先完成输入或上传，再固定范围。'}
async function poll(){if(!alive||!pending.value||!requestKey.value)return;try{const row=await request('/admin/exchange/ai/requests/'+requestKey.value);if(alive)callId.value=row.id}catch{/* Request may not be registered yet; no new model call is made. */}if(alive&&pending.value)timer=setTimeout(()=>void poll(),800)}
async function generate(){if(pending.value||props.disabled||!capture.value||!consent.value||!provider.value)return
 const payload={provider_id:provider.value,expected_config_revision:config.value.revision,action:action.value,type_slug:props.typeSlug,template_slug:props.templateSlug||null,title:props.title,display_date:props.displayDate||null,materials:materials.value,body:selectedText.value,body_format:capture.value.format,media_ids:selectedIds.value,photo_consent:sendPixels.value,preferences:temporary.value,consent:true}
 const fingerprint=JSON.stringify(payload)
 if(!requestKey.value||lastFingerprint!==fingerprint){requestKey.value=newId();lastFingerprint=fingerprint}
 const context=JSON.stringify([props.typeSlug,props.templateSlug,props.title,props.displayDate]);pending.value=true;emit('pending',true);error.value='';notice.value='';callId.value='';const token=requestKey.value;void poll()
 try{const value=await request('/admin/exchange/ai/generate',{method:'POST',body:JSON.stringify({...payload,request_key:token})});if(alive&&token===requestKey.value){if(context!==JSON.stringify([props.typeSlug,props.templateSlug,props.title,props.displayDate])){notice.value='生成期间文章结构或元信息已变化，候选未应用；请核对调用记录，不会自动重试计费。';return}result.value=value;notice.value=value.state==='cancelled'?'已取消应用结果；模型请求仍可能计费。':value.state==='succeeded'?'候选已校验，仅供预览；未修改当前文章。':'请到调用记录核对当前状态，重试相同输入不会重新调用模型。'}}catch(e){if(alive)error.value=(e instanceof Error?e.message:String(e))+'；再次点击将使用同一请求核对，不自动重复付费调用。'}finally{if(alive){pending.value=false;emit('pending',false);if(timer)clearTimeout(timer)}}}
watch([provider,action,materials,selectedIds,sendPixels,temporary],()=>{consent.value=false},{deep:true})
watch(provider,()=>{selectedIds.value=[];sendPixels.value=false})
watch(()=>!!(materials.value.trim()||selectedIds.value.length||Object.keys(temporary.value).length||result.value),value=>{if(props.creation)emit('dirty',value)})
watch(()=>[props.typeSlug,props.templateSlug,props.title,props.displayDate],()=>{consent.value=false;capture.value=null;result.value=null})
async function loadMedia(){mediaBusy.value=true;try{const result=await request('/admin/archive/media?'+new URLSearchParams({q:mediaQuery.value,page:'1',page_size:'12'}));if(alive)media.value=result.items}catch(e){if(alive)error.value=String(e)}finally{if(alive)mediaBusy.value=false}}
function choosePhoto(id:string){if(selectedIds.value.includes(id)){selectedIds.value=selectedIds.value.filter(v=>v!==id);if(!selectedIds.value.length)sendPixels.value=false}else if(selectedIds.value.length<5)selectedIds.value=[...selectedIds.value,id];else notice.value='每次最多明确选择5张照片。'}
function changePreference(key:string,event:Event){const value=(event.target as HTMLSelectElement).value;const next={...temporary.value};if(value==='')delete next[key];else next[key]=value==='true';temporary.value=next}

async function newRequest(){if(!await confirmAction('新调用可能再次计费。确认放弃复用原请求，并重新检查发送范围？'))return;requestKey.value='';lastFingerprint='';prepareRange()}
async function cancel(){if(!callId.value){notice.value='请求尚未登记，取消结果未确认；请稍后核对。';return}try{await request('/admin/exchange/ai/calls/'+callId.value+'/cancel',{method:'POST'});notice.value='已请求取消，等待服务响应或超时；不能保证停止计费。'}catch(e){error.value=String(e)}}
async function apply(mode:AIApply){if(!capture.value||!plainBody.value||props.disabled)return;if(!await confirmAction(mode==='replace'?'将候选正文替换当前全部正文？原文可撤销；不会自动发布。':'将候选应用到生成前固定的选区或光标？若正文已变化会拒绝，不会自动发布。'))return;const ok=props.apply(capture.value.id,candidate.value.body,mode);notice.value=ok?'候选已应用，可在编辑器撤销；保存仍使用原有草稿与并发保护。':'正文或编辑状态已变化，候选未应用，请重新固定范围。';if(ok)capture.value=null}
async function openDraft(){const id=result.value?.job_id;if(!id)return;if(props.creation){emit('preview',id);return;}sessionStorage.setItem('lj-exchange-job',id);await router.push('/admin/import')}
onMounted(async()=>{try{const value=await request('/admin/exchange/settings');if(alive){config.value=value;provider.value=(value.providers.find((p:any)=>p.id===value.default_provider&&p.enabled)||value.providers.find((p:any)=>p.enabled))?.id||''}}catch(e){if(alive)error.value=String(e)}})
onBeforeUnmount(()=>{alive=false;if(timer)clearTimeout(timer)})
</script>
<template><section class="writing-assistant"><h3>AI 写作助手</h3><p>模型与写作规则由管理员配置。只发送下方确认的文字，不会自动上传私人照片；只有另行勾选视觉授权才发送所选去元数据预览，没有模型时也可使用图文导入。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="config"><p v-if="!config.providers.some((p:any)=>p.enabled)">暂无启用模型。可在“AI与写作规则”配置，或下载规范使用 ChatGPT 网页版。</p><div class="assistant-fields"><label>写作模型<select aria-label="写作模型" v-model="provider" :disabled="pending||disabled"><option value="">请选择已启用模型</option><option v-for="p in config.providers.filter((p:any)=>p.enabled)" :key="p.id" :value="p.id">{{p.name}} · {{p.model}}</option></select></label><label v-if="!creation">写作操作<select aria-label="写作操作" v-model="action" :disabled="pending"><option v-for="[key,name] in actions" :key="key" :value="key">{{name}}</option></select></label><label v-if="!creation">发送的正文范围<select aria-label="发送的正文范围" v-model="scope" :disabled="pending" @change="capture=null;consent=false"><option value="selection">编辑器原选区</option><option value="body">当前完整正文</option><option value="none">只发送下方素材</option></select></label></div><button type="button" class="quiet" :disabled="pending||disabled" @click="prepareRange">固定选区与发送范围</button><pre v-if="capture" class="assistant-range">{{selectedText||'不发送正文，仅发送标题、展示日期、所选类型规范和下方素材。'}}</pre><label>写作素材与要求<textarea v-model="materials" rows="4" maxlength="30000" :disabled="pending"/></label><details><summary>参考照片与视觉授权（默认不发送图片）</summary><p>参考照片只发送服务器分配的局部引用名，不发送媒体 UUID、原始文件名或原图。看图另需模型视觉能力与下方授权。</p><div class="actions"><label>搜索参考照片<input v-model="mediaQuery" maxlength="100" :disabled="pending" @keydown.enter.prevent="!pending&&loadMedia()"></label><button type="button" class="quiet" :disabled="pending||mediaBusy" @click="loadMedia">查找媒体库照片</button></div><div class="assistant-photos"><button v-for="item in media" :key="item.id" type="button" class="quiet" :aria-pressed="selectedIds.includes(item.id)" :disabled="pending" @click="choosePhoto(item.id)"><PrivatePreview :id="item.id" :alt="item.alt||item.title||item.filename"/>{{selectedIds.includes(item.id)?'已选择 · ':''}}{{item.title||item.filename}}</button></div><p v-if="selectedIds.length">已明确选择 {{selectedIds.length}} / 5 张。以下是本次候选发送范围：</p><div class="assistant-photos"><PrivatePreview v-for="id in selectedIds" :key="id" :id="id" alt="本次选择的私人照片"/></div><label><input v-model="sendPixels" type="checkbox" :disabled="pending||!visionModel||!selectedIds.length">允许把上述所选照片的去 EXIF/GPS 预览发送给模型（不发送原图）</label><p v-if="!visionModel">此模型未配置视觉能力，不能发送图片像素；仍可引用选定照片进行排版。</p></details><details><summary>本次写作偏好（不修改全局设置）</summary><div class="assistant-fields"><label v-for="[key,label] in preferenceFlags" :key="key">{{label}}<select :value="key in temporary?String(temporary[key]):''" :disabled="pending" @change="changePreference(key,$event)"><option value="">继承已有规则</option><option value="true">启用</option><option value="false">关闭</option></select></label></div><label>本次文风<textarea :value="String(temporary.style||'')" rows="2" maxlength="4000" :disabled="pending" @input="temporary={...temporary,style:($event.target as HTMLTextAreaElement).value}"/></label></details><label><input v-model="consent" type="checkbox" :disabled="pending||!capture">我确认将标题、展示日期、所选正文范围和素材发送给所选模型</label><div class="actions"><button type="button" :disabled="pending||disabled||!capture||!consent||!provider||!typeSlug" @click="generate">{{pending?'正在生成候选…':'生成并预览'}}</button><button v-if="!pending&&(result||error)" type="button" class="quiet" @click="newRequest">新建一次调用（可能再次计费）</button><button v-if="pending" type="button" class="quiet" @click="cancel">请求取消</button></div></template>
<div v-if="candidate" class="assistant-result"><h4>候选：{{candidate.title}}</h4><ArticleBody :source="result.preview.records?.find((r:any)=>r.key===candidate.key)?.compiled_body||candidate.body" :format="2" :namespace="'ai-'+result.job_id" :preview-media="result.preview.images||[]"/><p v-if="candidate.summary">摘要建议：{{candidate.summary}}</p><p v-if="candidate.tags.length">标签建议：{{candidate.tags.join('、')}}</p><details><summary>字段、行程与校验结果</summary><pre>{{JSON.stringify({values:candidate.values,travel:candidate.travel,foods:candidate.foods,issues:result.preview.issues},null,2)}}</pre></details><p>结构化地点、照片和行程须到导入预览确认，不能直接粘贴带临时身份的正文。</p><div class="actions"><button v-if="!creation" type="button" class="quiet" :disabled="disabled||!capture||!plainBody" @click="apply('insert')">在原光标插入</button><button v-if="!creation" type="button" class="quiet" :disabled="disabled||!capture?.selection||!plainBody" @click="apply('selection')">替换原选区</button><button v-if="!creation" type="button" class="quiet" :disabled="disabled||!capture||!plainBody" @click="apply('replace')">替换全部正文</button><button type="button" :disabled="pending" @click="openDraft">转到导入预览创建新草稿</button></div></div></section></template>
<style scoped>
.writing-assistant{padding:clamp(12px,2vw,22px);border:1px solid var(--ui-line);border-radius:var(--ui-radius);background:var(--ui-card);margin-block:16px;min-width:0}.assistant-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px}.writing-assistant label{display:block}.writing-assistant textarea{width:100%;box-sizing:border-box}.writing-assistant input[type=checkbox]{width:auto}.writing-assistant pre{max-width:100%;white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;background:var(--ui-bg);padding:12px}.assistant-photos{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,120px),1fr));gap:8px}.assistant-photos button{min-width:0;overflow-wrap:anywhere}.assistant-photos :deep(img){max-width:100%;height:100px;object-fit:contain}.assistant-result{border-top:1px solid var(--ui-line);margin-top:20px;padding-top:12px}.writing-assistant .actions{flex-wrap:wrap}
</style>
